def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(cells) > 1 and color != background:
                components.append((
                    color,
                    min(y for y, x in cells), max(y for y, x in cells),
                    min(x for y, x in cells), max(x for y, x in cells)
                ))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            # Only isolated, non-background cells are stray marks.
            neighbors = [(r + dy, c + dx) for dy, dx in
                         ((1, 0), (-1, 0), (0, 1), (0, -1))
                         if 0 <= r + dy < h and 0 <= c + dx < w]
            if color == background or any(grid[y][x] == color for y, x in neighbors):
                continue

            containing = [
                (color2, (r2 - r1 + 1) * (c2 - c1 + 1))
                for color2, r1, r2, c1, c2 in components
                if r1 <= r <= r2 and c1 <= c <= c2
            ]
            if containing:
                out[r][c] = min(containing, key=lambda item: item[1])[0]
            else:
                out[r][c] = background
    return out
